import { get_location_details } from "@/mixins/GetLocations.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { create_project_site_user } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    repcreation: Boolean
  },
  mixins: [get_all_org_users, get_location_details],
  watch: {
    repcreation: {
      async handler() {
        if (this.repcreation == true) {
          this.stepperflow = 1;
          this.selectprojectsite = [];
          this.selectTeam = [];
          this.$store.commit("Setnamesearch", "");
          await Promise.all([this.get_all_org_users(), this.get_location_details()]);
          this.fetch_details();
        }
      },
      immediate: true
    }
  },
  data() {
    return {
      stepperflow: 1,
      userArray: [],
      selectTeam: [],
      searchF: "",
      loading: false,
      selectprojectsite: [],
      projectitems: [],
      searchV: ""
    };
  },
  methods: {
    nextstep() {
      if (this.$refs.form.validate()) {
        this.stepperflow = 2;
      }
    },
    close_dialog() {
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
      this.selectTeam = [];
      this.selectprojectsite = [];
      this.$emit("clicked", 0);
    },
    save_action() {
      if (this.$refs.form.validate()) {
        this.add_mutation();
      }
    },
    fetch_details() {
      this.projectitems = [];
      var loaction = this.locationList;
      loaction = loaction.filter(obj => obj.location_type == "PROJECT SITE");
      loaction.forEach(element => {
        this.projectitems.push({
          text: element.location_name,
          value: element.location_id
        });
      });
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
    },
    async add_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_project_site_user, {
          input: {
            user_email_id: [this.selectTeam],
            project_site_id: this.selectprojectsite
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_project_site_user);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "dataValue");
          this.$refs.form.resetValidation();
          this.$refs.form.reset();
          this.selectprojectsite = [];
          this.selectTeam = [];
          this.stepperflow = 1;
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
